package com.crosscheck.controller;
import com.crosscheck.model.*;import com.crosscheck.repository.*;import com.crosscheck.service.*;import com.lowagie.text.*;import com.lowagie.text.pdf.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.io.*;
@RestController @RequestMapping("/api/reports") public class ReportController{private final CandidateRepository repo;private final DocumentRepository docs;private final AuthService auth;private final AuditService audit;public ReportController(CandidateRepository r,DocumentRepository d,AuthService a,AuditService l){repo=r;docs=d;auth=a;audit=l;}@GetMapping(value="/candidate/{id}",produces=MediaType.APPLICATION_PDF_VALUE)public ResponseEntity<byte[]> report(@RequestHeader(value="Authorization",required=false)String h,@PathVariable Long id)throws Exception{User u=auth.require(h);Candidate c=repo.findById(id).orElseThrow();ByteArrayOutputStream out=new ByteArrayOutputStream();Document pdf=new Document(PageSize.A4,38,38,38,38);PdfWriter.getInstance(pdf,out);pdf.open();Font title=new Font(Font.HELVETICA,20,Font.BOLD,new java.awt.Color(6,87,200));Font h2=new Font(Font.HELVETICA,13,Font.BOLD,new java.awt.Color(12,31,64));pdf.add(new Paragraph("CrossCheck Candidate Risk Report",title));pdf.add(new Paragraph("Before You Hire — Verified Hiring Intelligence"));pdf.add(Chunk.NEWLINE);section(pdf,h2,"Candidate Details","Name: "+c.getName()+"\nEmail: "+c.getEmail()+"\nMobile: "+c.getMobileNumber()+"\nPosition: "+c.getPosition()+"\nExperience: "+c.getExperienceYears()+" years\nSkills: "+c.getSkills());section(pdf,h2,"Employment Verification","Current Company: "+c.getCurrentCompany()+"\nPrevious Company: "+c.getPreviousCompany()+"\nJoining Date: "+c.getJoiningDate()+"\nRelieving Date: "+c.getRelievingDate()+"\nEmployment Gap: "+c.getEmploymentGapMonths()+" months\nStatus: "+c.getEmploymentStatus());section(pdf,h2,"Education & Identity","Degree: "+c.getDegree()+"\nUniversity: "+c.getUniversity()+"\nYear: "+c.getGraduationYear()+"\nMarks: "+c.getMarks()+"\nEducation Status: "+c.getEducationStatus()+"\nIdentity Status: "+c.getIdentityStatus());section(pdf,h2,"Risk & Joining Intelligence","Risk Score: "+c.getRiskScore()+"/100\nRisk Level: "+c.getRiskLevel()+"\nJoining Probability: "+c.getJoiningProbability()+"%\nActive Offers: "+c.getActiveOffers());section(pdf,h2,"AI Recommendation",c.getAiRecommendation()+"\n"+c.getAiReason());section(pdf,h2,"Final Decision","Decision should be taken by the authorized HR or hiring manager after reviewing all supporting documents and checks.");pdf.close();audit.audit(u.getName(),"REPORT_DOWNLOADED","CANDIDATE",id.toString(),"PDF report downloaded");audit.notify("Report generated",c.getName()+" report was generated.","LOW");return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=CrossCheck-"+c.getName().replaceAll("\\s+","-")+".pdf").body(out.toByteArray());}private void section(Document d,Font h,String t,String body)throws Exception{d.add(new Paragraph(t,h));d.add(new Paragraph(body));d.add(Chunk.NEWLINE);}}
